content:
:root {
  --color-bg-base: #f1f5f9;
  --color-bg-surface: #ffffff;
  --color-bg-subtle: #f8fafc;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;

  --color-text-primary: #0f172a;
  --color-text-secondary: #475569;
  --color-text-muted: #94a3b8;

  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;

  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-danger: #ef4444;
  --color-danger-bg: #fef2f2;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ダッシュボード全体コンテナ */
.dashboard-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダー */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 8px;
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dashboard-title {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -0.02em;
}

.dashboard-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

/* 期間セレクタ */
.period-selector {
  display: inline-flex;
  align-items: center;
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 4px;
  gap: 4px;
  box-shadow: var(--shadow-sm);
}

.period-btn {
  border: none;
  background: transparent;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  white-space: nowrap;
}

.period-btn:hover {
  color: var(--color-text-primary);
  background-color: var(--color-bg-subtle);
}

.period-btn-active {
  background-color: var(--color-primary);
  color: #ffffff;
  font-weight: 600;
}

.period-btn-active:hover {
  background-color: var(--color-primary-hover);
  color: #ffffff;
}

/* KPIグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

/* KPIカード */
.kpi-card {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.kpi-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.kpi-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-secondary);
}

.kpi-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1;
}

.kpi-badge-up {
  background-color: var(--color-success-bg);
  color: var(--color-success);
}

.kpi-badge-down {
  background-color: var(--color-danger-bg);
  color: var(--color-danger);
}

.kpi-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.kpi-value {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.kpi-unit {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
}

.kpi-subtext {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* 共通セクションヘッダー */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
}

.section-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-primary);
}

/* チャートセクション */
.chart-section {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.chart-tab-group {
  display: inline-flex;
  background-color: var(--color-bg-subtle);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 3px;
  gap: 4px;
}

.chart-tab-btn {
  border: none;
  background: transparent;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
}

.chart-tab-btn:hover {
  color: var(--color-text-primary);
}

.chart-tab-btn-active {
  background-color: var(--color-bg-surface);
  color: var(--color-primary);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.chart-wrapper {
  width: 100%;
  height: 380px;
  margin-top: 8px;
}

/* チャートカスタムツールチップ */
.custom-tooltip {
  background-color: rgba(15, 23, 42, 0.94);
  color: #ffffff;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  font-size: 0.8125rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 6px;
  pointer-events: none;
}

.tooltip-label {
  font-weight: 700;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  padding-bottom: 4px;
  color: #e2e8f0;
}

.tooltip-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

/* データテーブルセクション */
.table-section {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
  text-align: left;
}

.data-table th,
.data-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.data-table th {
  background-color: var(--color-bg-subtle);
  font-weight: 600;
  color: var(--color-text-secondary);
}

.data-table tbody tr:hover {
  background-color: #f8fafc;
}

.data-table tbody tr:last-child td {
  border-bottom: none;
}

.text-right {
  text-align: right;
}

.positive-val {
  color: var(--color-success);
  font-weight: 600;
}

.negative-val {
  color: var(--color-danger);
  font-weight: 600;
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .dashboard-container {
    padding: 16px 12px 32px;
    gap: 16px;
  }

  .dashboard-title {
    font-size: 1.375rem;
  }

  .chart-section,
  .table-section {
    padding: 16px 12px;
  }

  .chart-wrapper {
    height: 300px;
  }

  .chart-tab-group {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
  }

  .chart-tab-btn {
    text-align: center;
  }

  .data-table th,
  .data-table td {
    padding: 10px 12px;
  }
}

export interface MonthlyData {
  month: string;
  sales: number;
  customers: number;
  averageSpend: number;
  targetSales: number;
}

export interface KpiCardData {
  id: string;
  title: string;
  value: string;
  subValue: string;
  changeRate: number;
  unit: string;
  isPositiveGood: boolean;
}

export type ChartViewType = 'all' | 'sales' | 'customers' | 'averageSpend';

export type PeriodType = 'year' | 'h1' | 'h2';

import { ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { KpiCardData } from '../types';

interface KpiCardProps {
  card: KpiCardData;
}

const KpiCard = ({ card }: KpiCardProps) => {
  const isPositive = card.changeRate >= 0;
  // isPositiveGoodに応じて上昇が良いか下降が良いかを判定
  const isGood = card.isPositiveGood ? isPositive : !isPositive;
  const badgeClass = isGood ? 'kpi-badge kpi-badge-up' : 'kpi-badge kpi-badge-down';
  const Icon = isPositive ? ArrowUpRight : ArrowDownRight;

  const formattedChangeRate = `${isPositive ? '+' : ''}${card.changeRate.toFixed(1)}%`;

  return (
    <div className="kpi-card">
      <div className="kpi-card-header">
        <span className="kpi-title">{card.title}</span>
        <span className={badgeClass}>
          <Icon size={14} />
          {formattedChangeRate}
        </span>
      </div>

      <div className="kpi-value-row">
        <span className="kpi-value">{card.value}</span>
        {card.unit && <span className="kpi-unit">{card.unit}</span>}
      </div>

      <div className="kpi-subtext">{card.subValue}</div>
    </div>
  );
};

export default KpiCard;

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from 'recharts';
import { MonthlyData, ChartViewType } from '../types';

interface ChartSectionProps {
  data?: MonthlyData[];
  activeView: ChartViewType;
  onViewChange?: (view: ChartViewType) => void;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload = [], label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-label">{label}の実績</div>
        {payload.map((entry, index) => {
          let formattedValue = '';
          if (entry.name === '売上高' || entry.name === '目標売上') {
            formattedValue = `¥${entry.value.toLocaleString()}`;
          } else if (entry.name === '客数') {
            formattedValue = `${entry.value.toLocaleString()} 名`;
          } else if (entry.name === '平均単価') {
            formattedValue = `¥${entry.value.toLocaleString()}`;
          } else {
            formattedValue = `${entry.value.toLocaleString()}`;
          }

          return (
            <div key={`item-${index}`} className="tooltip-item">
              <span style={{ color: entry.color }}>{entry.name}:</span>
              <strong>{formattedValue}</strong>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

const ChartSection = ({
  data = [],
  activeView,
  onViewChange
}: ChartSectionProps) => {
  const tabs: { type: ChartViewType; label: string }[] = [
    { type: 'all', label: '全体統合' },
    { type: 'sales', label: '売上・目標' },
    { type: 'customers', label: '客数推移' },
    { type: 'averageSpend', label: '平均単価' }
  ];

  return (
    <section className="chart-section">
      <div className="section-header">
        <h2 className="section-title">月次パフォーマンス推移</h2>
        <div className="chart-tab-group">
          {tabs.map((tab) => (
            <button
              key={tab.type}
              type="button"
              className={activeView === tab.type ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
              onClick={() => onViewChange?.(tab.type)}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={data} margin={{ top: 16, right: 16, left: 0, bottom: 8 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis
              dataKey="month"
              stroke="#64748b"
              fontSize={12}
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
            />
            {/* 左Y軸: 金額用（売上） */}
            {(activeView === 'all' || activeView === 'sales') && (
              <YAxis
                yAxisId="salesAxis"
                orientation="left"
                stroke="#64748b"
                fontSize={12}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
                tickFormatter={(value: number) => `¥${(value / 10000).toFixed(0)}万`}
              />
            )}

            {/* 客数専用Y軸 */}
            {activeView === 'customers' && (
              <YAxis
                yAxisId="customersAxis"
                orientation="left"
                stroke="#64748b"
                fontSize={12}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
                tickFormatter={(value: number) => `${value.toLocaleString()}名`}
              />
            )}

            {/* 平均単価専用Y軸 */}
            {activeView === 'averageSpend' && (
              <YAxis
                yAxisId="spendAxis"
                orientation="left"
                stroke="#64748b"
                fontSize={12}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
                tickFormatter={(value: number) => `¥${value.toLocaleString()}`}
              />
            )}

            {/* 右Y軸: 全体統合時の客数・客単価用 */}
            {activeView === 'all' && (
              <YAxis
                yAxisId="subAxis"
                orientation="right"
                stroke="#64748b"
                fontSize={12}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
                tickFormatter={(value: number) => `${value.toLocaleString()}`}
              />
            )}

            <Tooltip content={<CustomTooltip />} />
            <Legend verticalAlign="top" height={36} wrapperStyle={{ fontSize: '0.8125rem' }} />

            {/* 売上（棒グラフ） */}
            {(activeView === 'all' || activeView === 'sales') && (
              <Bar
                yAxisId="salesAxis"
                dataKey="sales"
                name="売上高"
                fill="#2563eb"
                radius={[4, 4, 0, 0]}
                barSize={activeView === 'all' ? 24 : 32}
              />
            )}

            {/* 目標売上（点線） */}
            {activeView === 'sales' && (
              <Line
                yAxisId="salesAxis"
                type="monotone"
                dataKey="targetSales"
                name="目標売上"
                stroke="#ef4444"
                strokeWidth={2}
                strokeDasharray="4 4"
                dot={{ r: 3, fill: '#ef4444' }}
              />
            )}

            {/* 客数（折れ線） */}
            {(activeView === 'all' || activeView === 'customers') && (
              <Line
                yAxisId={activeView === 'all' ? 'subAxis' : 'customersAxis'}
                type="monotone"
                dataKey="customers"
                name="客数"
                stroke="#10b981"
                strokeWidth={2.5}
                dot={{ r: 4, fill: '#10b981', strokeWidth: 1, stroke: '#ffffff' }}
                activeDot={{ r: 6 }}
              />
            )}

            {/* 客単価（折れ線） */}
            {(activeView === 'all' || activeView === 'averageSpend') && (
              <Line
                yAxisId={activeView === 'all' ? 'subAxis' : 'spendAxis'}
                type="monotone"
                dataKey="averageSpend"
                name="平均単価"
                stroke="#f59e0b"
                strokeWidth={2.5}
                dot={{ r: 4, fill: '#f59e0b', strokeWidth: 1, stroke: '#ffffff' }}
                activeDot={{ r: 6 }}
              />
            )}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
};

export default ChartSection;

import { MonthlyData } from '../types';

interface DataTableProps {
  data?: MonthlyData[];
}

const DataTable = ({ data = [] }: DataTableProps) => {
  return (
    <section className="table-section">
      <div className="section-header">
        <h2 className="section-title">月別実績明細</h2>
      </div>

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>対象月</th>
              <th className="text-right">売上高</th>
              <th className="text-right">目標売上</th>
              <th className="text-right">目標達成率</th>
              <th className="text-right">客数</th>
              <th className="text-right">平均客単価</th>
            </tr>
          </thead>
          <tbody>
            {data.map((item) => {
              const achievementRate = (item.sales / item.targetSales) * 100;
              const isAchieved = achievementRate >= 100;
              const achievementClass = isAchieved ? 'positive-val text-right' : 'negative-val text-right';

              return (
                <tr key={item.month}>
                  <td>{item.month}</td>
                  <td className="text-right">¥{item.sales.toLocaleString()}</td>
                  <td className="text-right">¥{item.targetSales.toLocaleString()}</td>
                  <td className={achievementClass}>
                    {achievementRate.toFixed(1)}%
                  </td>
                  <td className="text-right">{item.customers.toLocaleString()} 名</td>
                  <td className="text-right">¥{item.averageSpend.toLocaleString()}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
};

export default DataTable;

import { useState, useMemo } from 'react';
import { MonthlyData, KpiCardData, ChartViewType, PeriodType } from './types';
import KpiCard from './components/KpiCard';
import ChartSection from './components/ChartSection';
import DataTable from './components/DataTable';

const FULL_YEAR_DATA: MonthlyData[] = [
  { month: '1月', sales: 4250000, customers: 1420, averageSpend: 2993, targetSales: 4000000 },
  { month: '2月', sales: 3890000, customers: 1290, averageSpend: 3015, targetSales: 3900000 },
  { month: '3月', sales: 4620000, customers: 1510, averageSpend: 3060, targetSales: 4300000 },
  { month: '4月', sales: 4880000, customers: 1580, averageSpend: 3088, targetSales: 4600000 },
  { month: '5月', sales: 5120000, customers: 1640, averageSpend: 3122, targetSales: 4900000 },
  { month: '6月', sales: 4760000, customers: 1530, averageSpend: 3111, targetSales: 4800000 },
  { month: '7月', sales: 5350000, customers: 1690, averageSpend: 3166, targetSales: 5100000 },
  { month: '8月', sales: 5680000, customers: 1780, averageSpend: 3191, targetSales: 5400000 },
  { month: '9月', sales: 4950000, customers: 1570, averageSpend: 3153, targetSales: 5000000 },
  { month: '10月', sales: 5240000, customers: 1630, averageSpend: 3215, targetSales: 5100000 },
  { month: '11月', sales: 5490000, customers: 1680, averageSpend: 3268, targetSales: 5200000 },
  { month: '12月', sales: 6380000, customers: 1890, averageSpend: 3376, targetSales: 6000000 }
];

const App = () => {
  const [period, setPeriod] = useState<PeriodType>('year');
  const [chartView, setChartView] = useState<ChartViewType>('all');

  // 選択された期間に応じたデータの絞り込み
  const filteredData = useMemo(() => {
    if (period === 'h1') {
      return FULL_YEAR_DATA.slice(0, 6);
    }
    if (period === 'h2') {
      return FULL_YEAR_DATA.slice(6, 12);
    }
    return FULL_YEAR_DATA;
  }, [period]);

  // KPIカード用の集計計算
  const kpiCards: KpiCardData[] = useMemo(() => {
    const totalSales = filteredData.reduce((sum, item) => sum + item.sales, 0);
    const totalTarget = filteredData.reduce((sum, item) => sum + item.targetSales, 0);
    const totalCustomers = filteredData.reduce((sum, item) => sum + item.customers, 0);
    const avgSpend = Math.round(totalSales / (totalCustomers || 1));

    // 最新月と前月の比較（前期比）
    const latestMonth = filteredData[filteredData.length - 1];
    const prevMonth = filteredData.length > 1 ? filteredData[filteredData.length - 2] : null;

    // 売上前月比
    const salesChange = prevMonth ? ((latestMonth.sales - prevMonth.sales) / prevMonth.sales) * 100 : 0;
    // 客数前月比
    const customersChange = prevMonth ? ((latestMonth.customers - prevMonth.customers) / prevMonth.customers) * 100 : 0;
    // 平均客単価前月比
    const spendChange = prevMonth ? ((latestMonth.averageSpend - prevMonth.averageSpend) / prevMonth.averageSpend) * 100 : 0;

    // 目標達成率
    const targetAchievementRate = ((totalSales - totalTarget) / totalTarget) * 100;

    return [
      {
        id: 'sales',
        title: '総売上高',
        value: `¥${totalSales.toLocaleString()}`,
        subValue: `直近月実績: ¥${latestMonth.sales.toLocaleString()} (前月差: ${prevMonth ? (latestMonth.sales >= prevMonth.sales ? '+' : '') + (latestMonth.sales - prevMonth.sales).toLocaleString() : '0'}円)`,
        changeRate: salesChange,
        unit: '円',
        isPositiveGood: true
      },
      {
        id: 'target',
        title: '目標売上達成度',
        value: `${((totalSales / totalTarget) * 100).toFixed(1)}%`,
        subValue: `目標: ¥${totalTarget.toLocaleString()} (差額: ${totalSales >= totalTarget ? '+' : ''}${(totalSales - totalTarget).toLocaleString()}円)`,
        changeRate: targetAchievementRate,
        unit: '',
        isPositiveGood: true
      },
      {
        id: 'customers',
        title: '総来客数',
        value: totalCustomers.toLocaleString(),
        subValue: `直近月客数: ${latestMonth.customers.toLocaleString()}名 (前月差: ${prevMonth ? (latestMonth.customers >= prevMonth.customers ? '+' : '') + (latestMonth.customers - prevMonth.customers).toLocaleString() : '0'}名)`,
        changeRate: customersChange,
        unit: '名',
        isPositiveGood: true
      },
      {
        id: 'averageSpend',
        title: '期間平均客単価',
        value: `¥${avgSpend.toLocaleString()}`,
        subValue: `直近月単価: ¥${latestMonth.averageSpend.toLocaleString()} (前月差: ${prevMonth ? (latestMonth.averageSpend >= prevMonth.averageSpend ? '+' : '') + (latestMonth.averageSpend - prevMonth.averageSpend).toLocaleString() : '0'}円)`,
        changeRate: spendChange,
        unit: '円',
        isPositiveGood: true
      }
    ];
  }, [filteredData]);

  return (
    <div className="dashboard-container">
      {/* ヘッダーエリア */}
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="dashboard-title">売上分析ダッシュボード</h1>
          <p className="dashboard-subtitle">月次推移および主要KPIのリアルタイム集計・モニタリング</p>
        </div>

        {/* 期間切り替えセレクター */}
        <div className="period-selector">
          <button
            type="button"
            className={period === 'year' ? 'period-btn period-btn-active' : 'period-btn'}
            onClick={() => setPeriod('year')}
          >
            年間 (通期)
          </button>
          <button
            type="button"
            className={period === 'h1' ? 'period-btn period-btn-active' : 'period-btn'}
            onClick={() => setPeriod('h1')}
          >
            上半期 (1〜6月)
          </button>
          <button
            type="button"
            className={period === 'h2' ? 'period-btn period-btn-active' : 'period-btn'}
            onClick={() => setPeriod('h2')}
          >
            下半期 (7〜12月)
          </button>
        </div>
      </header>

      {/* KPIサマリーカード */}
      <section className="kpi-grid">
        {kpiCards.map((card) => (
          <KpiCard key={card.id} card={card} />
        ))}
      </section>

      {/* 月次グラフ推移セクション */}
      <ChartSection
        data={filteredData}
        activeView={chartView}
        onViewChange={(view) => setChartView(view)}
      />

      {/* 詳細データテーブルセクション */}
      <DataTable data={filteredData} />
    </div>
  );
};

export default App;
